const body = $input.first().json.body || $input.first().json;
const userRole = (body.user_role || "").trim();
const PERMITTED_AGENT_ROLES = ["Engineering_Manager", "Product_Owner"];

if (!PERMITTED_AGENT_ROLES.includes(userRole)) {
  return [{
    json: {
      authorized: false,
      status_code: 403,
      error: "AGENT_AUTHORIZATION_DENIED",
      message: `Deterministic Policy Denial: Role '${userRole}' is not authorized to invoke BRD-to-Engineering cognitive agents. Permitted roles: ${PERMITTED_AGENT_ROLES.join(", ")}.`,
      user_role: userRole,
      submitted_by: body.submitted_by || "unknown"
    }
  }];
}

const rawText = (body.brd_text || "").trim();
const title = (body.title || "Untitled BRD").trim();
const submittedBy = (body.submitted_by || "engineering_manager").trim();

if (rawText.length < 50) {
  throw new Error("GUARDRAIL_REJECTED: BRD text is too short (< 50 chars). Please provide valid requirements.");
}
if (rawText.length > 25000) {
  throw new Error("GUARDRAIL_REJECTED: BRD text exceeds maximum 25,000 character limit.");
}

// Lightweight deterministic hash for audit logs (zero raw PII in logs)
let hash = 0;
for (let i = 0; i < rawText.length; i++) {
  hash = ((hash << 5) - hash) + rawText.charCodeAt(i);
  hash |= 0;
}

return [{
  json: {
    authorized: true,
    user_role: userRole,
    title: body.title || "Untitled BRD",
    submitted_by: submittedBy,
    brd_text: rawText,
    content_hash: "sha256_sim_" + Math.abs(hash).toString(16),
    simulate_fault: Boolean(body.simulate_fault)
  }
}];

