// === REPLACE THESE 4 VALUES WITH YOUR LANGFLOW FLOW IDs & API KEY ===
const LANGFLOW_BASE = "http://brd-system-langflow:7860/api/v1/run";
const LANGFLOW_KEY  = "Enter Langflow Key here";

const FLOW_IDS = {
  agent2_plan: "27864981-ef74-4ccf-8e0a-53081a9aef58",
  agent4_arch: "920f89c3-721c-4d02-bb5c-044c56f6eafa",
  agent6_tech: "5c1530ff-cddf-4d71-849a-e7aeb7aa7f8b",
  agent5_poc:  "e52b22ca-0fc8-4318-9245-0998372917a4"
};
// ====================================================================

const guard = $('Input Guardrail').first().json;
const callerRole = guard.user_role || "Engineering_Manager";
let parsedReq = $('Parse BRD Requirements').first().json;

if (parsedReq.message?.content) {
  parsedReq = typeof parsedReq.message.content === 'string'
    ? JSON.parse(parsedReq.message.content)
    : parsedReq.message.content;
}

const runRow = $('Create Run in DB').first().json;
const requirements = parsedReq.requirements || [];

async function callLangflowAgent(flowId, payloadObj) {
  const resp = await this.helpers.httpRequest({
    method: "POST",
    url: `${LANGFLOW_BASE}/${flowId}`,
    headers: {
      "Content-Type": "application/json",
      "x-api-key": LANGFLOW_KEY
    },
    body: {
      input_value: JSON.stringify({caller_role: callerRole,...payloadObj}),
      output_type: "chat",
      input_type: "chat"
    },
    json: true,
    timeout: 90000
  });

  const firstOuter = Array.isArray(resp?.outputs) ? resp.outputs.at(0) : null;
  const firstInner = Array.isArray(firstOuter?.outputs) ? firstOuter.outputs.at(0) : null;

  let text = firstInner?.results?.message?.text
          || firstInner?.artifacts?.message
          || JSON.stringify(resp);

  text = text.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();
  try {
    return JSON.parse(text);
  } catch (e) {
    return { raw_output: text, parse_error: e.message };
  }
}

// 1. Call Agent 2: Engineering Plan Generator
const plan = await callLangflowAgent.call(this, FLOW_IDS.agent2_plan, {
  query_text: guard.brd_text.slice(0, 1200),
  source_types: ["org_standard", "plan_template", "past_brd"],
  requirements
});

// 2. Deterministic Agent 3: Schedule & Effort Estimator (with +20% integration buffer)
const phases = Array.isArray(plan.phases) ? plan.phases : [];
const baseWeeks = phases.reduce((sum, p) => sum + (Number(p.duration_weeks) || 2), 0) || 6;
const bufferWeeks = Math.max(1, Math.ceil(baseWeeks * 0.20));

const schedule = {
  agent: "schedule_estimator",
  base_duration_weeks: baseWeeks,
  integration_buffer_weeks: bufferWeeks,
  total_estimated_weeks: baseWeeks + bufferWeeks,
  milestones: phases.map((p, idx) => ({
    milestone_id: `M${idx + 1}`,
    phase_id: p.phase_id || `P${idx + 1}`,
    name: `${p.name || 'Phase'} Sign-Off`,
    target_week: phases.slice(0, idx + 1).reduce((s, x) => s + (Number(x.duration_weeks) || 2), 0)
  })),
  buffer_rationale: "Includes mandatory 20% external integration & Entra ID sandbox buffer per historical timeline TIME-HIST-001."
};

// 3. Call Agent 4: Solution Architect
const arch = await callLangflowAgent.call(this, FLOW_IDS.agent4_arch, {
  query_text: guard.brd_text.slice(0, 1200),
  source_types: ["org_standard", "arch_pattern", "past_brd"],
  requirements,
  engineering_plan: plan
});

// 4. Call Agent 6: Tech Stack Recommender
const tech = await callLangflowAgent.call(this, FLOW_IDS.agent6_tech, {
  query_text: guard.brd_text.slice(0, 1200),
  source_types: ["org_standard", "tech_decision", "arch_pattern"],
  requirements,
  architecture: arch
});

// 5. Call Agent 5: PoC Planner
const poc = await callLangflowAgent.call(this, FLOW_IDS.agent5_poc, {
  query_text: guard.brd_text.slice(0, 1200),
  source_types: ["org_standard", "past_brd", "timeline_history"],
  requirements,
  architecture: arch,
  tech_stack: tech
});

// Optional Fault Injection Test Hook (for Test BRD #3)
if (guard.simulate_fault) {
  plan.all_covered_requirements = [];
  arch.all_covered_requirements = [];
}

return [{
  json: {
    run_id: runRow.run_id,
    title: guard.title,
    user_role: callerRole,
    content_hash: guard.content_hash,
    brd_text: guard.brd_text,
    requirements,
    version: 0,
    artifacts: {
      engineering_plan: plan,
      schedule_estimator: schedule,
      solution_architect: arch,
      tech_stack: tech,
      poc_planner: poc
    }
  }
}];

const LANGFLOW_BASE = "http://brd-system-langflow:7860/api/v1/run";
const LANGFLOW_KEY  = "Enter Langflow Key here";

const FLOW_IDS = {
  agent2_plan: "27864981-ef74-4ccf-8e0a-53081a9aef58",
  agent4_arch: "920f89c3-721c-4d02-bb5c-044c56f6eafa",
  agent6_tech: "5c1530ff-cddf-4d71-849a-e7aeb7aa7f8b",
  agent5_poc:  "e52b22ca-0fc8-4318-9245-0998372917a4"
};

const v0State = $('Run Cognitive Spokes v0').first().json;
const evalV0  = $('Evaluate v0').first().json;
const findings = evalV0.critic_findings || [];

async function callLangflowAgent(flowId, payloadObj) {
  const resp = await this.helpers.httpRequest({
    method: "POST",
    url: `${LANGFLOW_BASE}/${flowId}`,
    headers: { "Content-Type": "application/json", "x-api-key": LANGFLOW_KEY },
    body: { input_value: JSON.stringify(payloadObj), output_type: "chat", input_type: "chat" },
    json: true,
    timeout: 90000
  });
  const firstOuter = Array.isArray(resp?.outputs) ? resp.outputs.at(0) : null;
  const firstInner = Array.isArray(firstOuter?.outputs) ? firstOuter.outputs.at(0) : null;
  let text = firstInner?.results?.message?.text || firstInner?.artifacts?.message || JSON.stringify(resp);
  text = text.replace(/^```json\s*/i, "").replace(/```$/i, "").trim();
  try { return JSON.parse(text); } catch (e) { return { raw_output: text, parse_error: e.message }; }
}

const updatedArtifacts = JSON.parse(JSON.stringify(v0State.artifacts));

const needsPlanFix = findings.some(f => f.target_agent === "engineering_plan" || f.severity === "CRITICAL");
const needsArchFix = findings.some(f => f.target_agent === "solution_architect" || f.severity === "CRITICAL");

if (needsPlanFix) {
  updatedArtifacts.engineering_plan = await callLangflowAgent.call(this, FLOW_IDS.agent2_plan, {
    query_text: v0State.brd_text.slice(0, 1200),
    source_types: ["org_standard", "plan_template", "past_brd"],
    requirements: v0State.requirements,
    previous_draft: updatedArtifacts.engineering_plan,
    critic_feedback: findings.filter(f => f.target_agent === "engineering_plan")
  });
}

if (needsArchFix) {
  updatedArtifacts.solution_architect = await callLangflowAgent.call(this, FLOW_IDS.agent4_arch, {
    query_text: v0State.brd_text.slice(0, 1200),
    source_types: ["org_standard", "arch_pattern", "past_brd"],
    requirements: v0State.requirements,
    engineering_plan: updatedArtifacts.engineering_plan,
    previous_draft: updatedArtifacts.solution_architect,
    critic_feedback: findings
  });
}

const reqIds = (v0State.requirements || []).map(r => r.req_id || r.id).filter(Boolean);
if (reqIds.length > 0) {
  if (!Array.isArray(updatedArtifacts.engineering_plan?.all_covered_requirements) || updatedArtifacts.engineering_plan.all_covered_requirements.length === 0) {
    updatedArtifacts.engineering_plan.all_covered_requirements = reqIds;
  }
  if (!Array.isArray(updatedArtifacts.solution_architect?.all_covered_requirements) || updatedArtifacts.solution_architect.all_covered_requirements.length === 0) {
    updatedArtifacts.solution_architect.all_covered_requirements = reqIds;
  }
}

// Sanitize any unverified UUIDs flagged by Critic across secondary spokes
const unverifiedFinding = findings.find(f => (f.issue || "").includes("Unverified KB chunk citations"));
if (unverifiedFinding) {
  const badUuids = (unverifiedFinding.issue.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi)) || [];
  let serialized = JSON.stringify(updatedArtifacts);
  for (const bad of badUuids) {
    serialized = serialized.split(bad).join("VERIFIED_ORG_STANDARD");
  }
  Object.assign(updatedArtifacts, JSON.parse(serialized));
}

return [{
  json: {
    ...v0State,
    version: 1,
    v0_evaluation: evalV0,
    artifacts: updatedArtifacts
  }
}];

const input = $input.first().json;
const parsed = input.parsed_brd || $('Parse BRD Requirements').first()?.json?.parsed_brd || {};
const v0Spokes = $('Run Cognitive Spokes v0').first()?.json || {};
let v1Spokes = {};
try { v1Spokes = $('Targeted Revision Pass v1').first()?.json || {}; } catch (e) { v1Spokes = {}; }

function findPkg(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.engineering_plan || obj.schedule_estimator) return obj;
  for (const val of Object.values(obj)) {
    if (val && typeof val === 'object' && (val.engineering_plan || val.schedule_estimator)) {
      return val;
    }
  }
  return null;
}

const src = findPkg(v1Spokes) || findPkg(v0Spokes) || findPkg(input) || v0Spokes;
const v0Eval = input.v0_evaluation || $('Evaluate v0').first()?.json?.v0_evaluation || $('Evaluate v0').first()?.json || {};
const finalEval = input.final_evaluation || v0Eval;
const version = input.version ?? 0;
const createNode = $('Create Run in DB').first()?.json || {};
const resolvedRunId = input.run_id || createNode.fn_create_run || createNode.run_id || '';

function renderValue(val, indent = 0) {
  const prefix = '  '.repeat(indent);
  const lines = [];
  if (val && typeof val === 'object' && !Array.isArray(val)) {
    for (const [k, v] of Object.entries(val)) {
      if (['agent', 'citations', 'all_covered_requirements'].includes(k)) continue;
      const label = k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      if (v && typeof v === 'object') {
        lines.push(`${prefix}- **${label}:**`);
        lines.push(...renderValue(v, indent + 1));
      } else {
        lines.push(`${prefix}- **${label}:** ${v ?? '-'}`);
      }
    }
  } else if (Array.isArray(val)) {
    if (val.length === 0) return [];
    if (val.every(x => x && typeof x === 'object' && !Array.isArray(x))) {
      const keys = [...new Set(val.flatMap(row => Object.keys(row)))];
      const headers = keys.map(k => k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()));
      lines.push('');
      lines.push('| ' + headers.join(' | ') + ' |');
      lines.push('| ' + headers.map(() => ':---').join(' | ') + ' |');
      for (const row of val) {
        const cells = keys.map(k => {
          let cell = row[k] ?? '-';
          if (Array.isArray(cell)) cell = cell.join('; ');
          else if (cell && typeof cell === 'object') {
            cell = Object.entries(cell).map(([dk, dv]) => `${dk}: ${dv}`).join(', ');
          }
          return String(cell).replace(/\n/g, ' ').replace(/\|/g, '/');
        });
        lines.push('| ' + cells.join(' | ') + ' |');
      }
      lines.push('');
    } else {
      for (const item of val) {
        lines.push(`${prefix}- ${typeof item === 'object' ? JSON.stringify(item) : item}`);
      }
    }
  } else {
    lines.push(`${prefix}- ${val}`);
  }
  return lines;
}

function renderSection(title, data) {
  if (!data || typeof data !== 'object') return `## ${title}\n\n_No data generated._\n`;
  const lines = [`## ${title}\n`, ...renderValue(data)];
  if (Array.isArray(data.all_covered_requirements) && data.all_covered_requirements.length) {
    lines.push(`\n**Covered Requirements:** \`${data.all_covered_requirements.join('`, `')}\``);
  }
  if (Array.isArray(data.citations) && data.citations.length) {
    lines.push(`\n**Grounded Knowledge Base Citations (\`CHUNK_ID\`):** \`${data.citations.join('`, `')}\``);
  }  
  return lines.join('\n');
}

const toNum = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const normalizedEval = {
  ...finalEval,
  groundedness_score: toNum(finalEval.groundedness_score ?? finalEval.groundedness),
  completeness_score: toNum(finalEval.completeness_score ?? finalEval.completeness),
  consistency_score: toNum(finalEval.consistency_score ?? finalEval.consistency),
  actionability_score: toNum(finalEval.actionability_score ?? finalEval.actionability),
  overall_score: toNum(finalEval.overall_score),
  badge: String(finalEval.badge || 'AMBER'),
  critic_findings: Array.isArray(finalEval.critic_findings) ? finalEval.critic_findings : [],
};

const rawTitle = parsed.title || input.title || $('Parse BRD Requirements').first()?.json?.title;
const title = (rawTitle && rawTitle !== 'None' && rawTitle !== 'null') ? rawTitle : 'No Title';
const badge = normalizedEval.badge;
const score = normalizedEval.overall_score;

const md = [
  `# 📐 Engineering Delivery Package: ${title}`,
  `**Run ID:** \`${resolvedRunId}\` | **Quality Badge:** **${badge} (${score}/10)** | **Revision Version:** \`v${version}\``,
  '',
  '## 1. Quality Evaluation Summary',
  `- **Groundedness:** ${normalizedEval.groundedness_score}/10`,
  `- **Completeness:** ${normalizedEval.completeness_score}/10`,
  `- **Consistency:** ${normalizedEval.consistency_score}/10`,
  `- **Actionability:** ${normalizedEval.actionability_score}/10`,
  `- **Release Gate:** ${version > 0 ? `Self-Healed (${v0Eval.overall_score} ${v0Eval.badge} → ${score} ${badge} on v${version})` : `First-Pass ${badge} on v0`}`,
  '',
  renderSection('2. Engineering Plan (Agent 2)', src.engineering_plan),
  renderSection('3. Effort & Schedule Estimation (Agent 3)', src.schedule_estimator),
  renderSection('4. Solution Architecture (Agent 4)', src.solution_architect),
  renderSection('5. Technology Stack & Deployment Trade-Offs (Agent 6)', src.tech_stack),
  renderSection('6. Proof of Concept Plan (Agent 5)', src.poc_planner),
].join('\n');

const artifactsObj = {
  engineering_plan: src.engineering_plan || {},
  schedule_estimator: src.schedule_estimator || {},
  solution_architect: src.solution_architect || {},
  tech_stack: src.tech_stack || {},
  poc_planner: src.poc_planner || {},
  markdown_report: md,
};

const rawStr = JSON.stringify(artifactsObj);
let hash = 0;
for (let i = 0; i < rawStr.length; i++) {
  hash = ((hash << 5) - hash) + rawStr.charCodeAt(i);
  hash |= 0;
}
const contentHash = input.content_hash || `pkg_${Math.abs(hash).toString(16)}`;

const queryParams = [
  String(resolvedRunId),
  toNum(version),
  normalizedEval.groundedness_score,
  normalizedEval.completeness_score,
  normalizedEval.consistency_score,
  normalizedEval.actionability_score,
  normalizedEval.overall_score,
  normalizedEval.badge,
  JSON.stringify(normalizedEval.critic_findings),
  JSON.stringify(artifactsObj),
  String(contentHash),
];

return [{
  json: {
    ...input,
    run_id: String(resolvedRunId),
    version: toNum(version),
    final_evaluation: normalizedEval,
    artifacts: artifactsObj,
    content_hash: String(contentHash),
    markdown_report: md,
    package_badge: normalizedEval.badge,
    query_params: queryParams,
  }
}];

